INSERT INTO results (country_id, points, position, year, artist, song, info, img)
VALUES
    (10, 516, 1, 2026, 'Dara', 'Bangaranga', 'Bulgaria did something unusual. First, a national selection chose DARA as the artist. Then she performed three possible songs, with public and jury votes choosing Bangaranga.', 'https://photos.ebu.ch/media/image?src=thumbs/37741_1250_m.jpg&1788331859'),   -- Bulgaria
    (24, 343, 2, 2026, 'Noam Bettan', 'Michelle', 'Israel used HaKokhav HaBa (The Rising Star), its long-running televised talent competition. Noam won the 2026 edition through a combination of judges and public voting.', 'https://photos.ebu.ch/media/image?src=thumbs/37687_1250_m.jpg&1788330715'),   -- Israel
    (39, 296, 3, 2026, 'Alexandra Capitanescu', 'Choke Me', 'Romania returned to Eurovision in 2026 after taking two years away. Before that, its best results were two third-place finishes.', 'https://photos.ebu.ch/media/image?src=thumbs/37747_1250_m.jpg&1788332968'),   -- Romania
    (4, 287, 4, 2026, 'Delta Goodrem', 'Eclipse', 'Delta Goodrem is a HUGE Australian pop star. She has sold more than nine million albums, had five No.1 albums and nine No.1 singles, and won 12 ARIA Awards.', 'https://photos.ebu.ch/media/image?src=thumbs/37955_1250_m.jpg&1788331422'),    -- Australia
    (25, 281, 5, 2026, 'Sal Da Vinci', 'Per Sempre Si', 'Since returning to Eurovision in 2011, Italy has consistently finished in the Top 10, except for two occasions, when they placed 16th and 21st.', 'https://photos.ebu.ch/media/image?src=thumbs/37973_1250_m.jpg&1788332823'),   -- Italy
    (16, 279, 6, 2026, 'Linda Lampenius x Pete Parkkonen', 'Liekinheitin', 'Liekinheitin means Flamethrower. It combines rock, classical violin and dance music, while describing an intense and complicated attraction', 'https://photos.ebu.ch/media/image?src=thumbs/37677_1250_m.jpg&1788332339'),   -- Finland
    (14, 243, 7, 2026, 'Soren Torpegaard Lund', 'For Vi Gar Hjem', 'For Vi Gar Hjem means roughly Before We Go Home. It''s a Danish-language song with a more intimate, emotional Nordic feel.', 'https://photos.ebu.ch/media/image?src=thumbs/37769_1250_m.jpg&1788333049'),   -- Denmark
    (30, 226, 8, 2026, 'Satoshi', 'Viva, Moldova!', 'Moldova has become one of Eurovision''s most distinctive countries despite its small size. 2026 was also its return to Eurovision after taking 2025 off.', 'https://photos.ebu.ch/media/image?src=thumbs/37659_1250_m.jpg&1788332259'),   -- Moldova
    (50, 221, 9, 2026, 'LELEKA', 'Ridnym', 'Ukraine is one of Eurovisions strongest modern countries, with three victories in the 21st century, tying Sweden for the most wins during this period.', 'https://photos.ebu.ch/media/image?src=thumbs/37962_1250_m.jpg&1788331124'),   -- Ukraine
    (20, 220, 10, 2026, 'Akylas', 'Ferto', 'Akylas is a young artist from Serres who became known through viral performances and TikTok. His sound combines modern pop with Greek influences.', 'https://photos.ebu.ch/media/image?src=thumbs/37668_1250_m.jpg&1788331064'),  -- Greece
    (17, 158, 11, 2026, 'Monroe', 'Regarde !', 'Monroe is remarkably young, only 17, but already won France Télévisions'' Prodiges talent competition.', 'https://photos.ebu.ch/media/image?src=thumbs/37981_1250_m.jpg&1788332158'),  -- France
    (37, 150, 12, 2026, 'Alicja', 'Pray', 'ALICJA first became widely known after winning The Voice of Poland and has since established herself as a distinctive singer-songwriter.', 'https://photos.ebu.ch/media/image?src=thumbs/37736_1250_m.jpg&1788332425'),  -- Poland
    (1, 145, 13, 2026, 'Alis', 'Nan', 'Alis is only 21 but already won X Factor Albania. He''s a multi-instrumentalist who plays piano and guitar.', 'https://photos.ebu.ch/media/image?src=thumbs/37964_1250_m.jpg&1788330932'),   -- Albania
    (36, 134, 14, 2026, 'Jonas Lovv', 'Ya Ya Ya', 'YA YA YA is an energetic, playful song about being yourself and not caring too much about what other people think.', 'https://photos.ebu.ch/media/image?src=thumbs/37976_1250_m.jpg&1788332901'),  -- Norway
    (11, 124, 15, 2026, 'Lelek', 'Andromeda', 'Croatia has never won Eurovision, although it has had several memorable entries. Best result, 2024 with Rim Tim Tagi Dim', 'https://photos.ebu.ch/media/image?src=thumbs/37666_1250_m.jpg&1788332016'),  -- Croatia
    (13, 113, 16, 2026, 'Daniel Zizka', 'Crossroads', 'Czechia used an internal selection, choosing Daniel and then revealing CROSSROADS separately. Daniel himself said he wanted to bring music and emotion rather than hide behind spectacle', 'https://photos.ebu.ch/media/image?src=thumbs/37752_1250_m.jpg&1788331769'),  -- Czech Republic
    (42, 90, 17, 2026, 'Lavina', 'Kraj mene', 'Kraj Mene has a darker, heavier and more introspective character. Be careful.', 'https://photos.ebu.ch/media/image?src=thumbs/37737_1250_m.jpg&1788331548'),   -- Serbia
    (29, 89, 18, 2026, 'Aidan', 'Bella', 'Malta is one of Eurovision''s smallest countries but has been extremely committed to the contest. It has never won.', 'https://photos.ebu.ch/media/image?src=thumbs/37970_1250_m.jpg&1788331669'),   -- Malta
    (12, 75, 19, 2026, 'Antigoni', 'Jalla', 'JALLA means “more” in the Cypriot dialect. It''s an upbeat party track combining traditional sounds with huge modern beats.', 'https://photos.ebu.ch/media/image?src=thumbs/37761_1250_m.jpg&1788332640'),   -- Cyprus
    (47, 51, 20, 2026, 'Felicia', 'My System', 'Sweden doing Sweden. Pay attention to the staging, choreography and polished pop production.', 'https://photos.ebu.ch/media/image?src=thumbs/37662_1250_m.jpg&1788333476'),   -- Sweden
    (8, 36, 21, 2026, 'Essyla', 'Dancing on the Ice', 'Belgium was one of the seven countries at the very first Eurovision in 1956. Its only victory came in 1986 with Sandra Kim.', 'https://photos.ebu.ch/media/image?src=thumbs/37726_1250_m.jpg&1788330820'),    -- Belgium
    (27, 22, 22, 2026, 'Lion Ceccah', 'Solo Quiero Más', 'Interestingly, Sólo Quiero Más is multilingual, combining Lithuanian, Spanish and English. The title means I only want more.', 'https://photos.ebu.ch/media/image?src=thumbs/37729_1250_m.jpg&1788332506'),   -- Lithuania
    (19, 12, 23, 2026, 'Sarah Engels', 'Fire', 'Sarah Engels became famous through Deutschland sucht den Superstar in 2011. Since then she has had a successful music, television and musical-theatre career.', 'https://photos.ebu.ch/media/image?src=thumbs/37979_1250_m.jpg&1788330567'),   -- Germany
    (5, 6, 24, 2026, 'Cosmo', 'Tanzschein', 'Austria is the host country in 2026 because JJ won Eurovision 2025 with Wasted Love.', 'https://photos.ebu.ch/media/image?src=thumbs/37985_1250_m.jpg&1788333026'),     -- Austria
    (51, 1, 25, 2026, 'Look Mum No Computer', 'Eins, Zwei, Drei', 'Eins, Zwei, Drei is an eccentric electronic song about escaping the boredom of everyday 9-to-5 life.', 'https://photos.ebu.ch/media/image?src=thumbs/37984_1250_m.jpg&1788332087');    -- United Kingdom
